using System;
using BoscaliSummer.Modules.Hud.Domain;

namespace BoscaliSummer.Tests.Features.Hud
{
    /// <summary>The line art's crop table (the ink box of each vanilla sprite, generated by tools/Build-StoreArtBounds.py) and how a picture is fitted in its box.</summary>
    internal static class StoreArtTests
    {
        public static void Run()
        {
            Bounds();
            Fit();
            Slice();
        }

        private static void Ink(string sprite, float w, float h, int x0, int y0, int x1, int y1)
        {
            TestAssert.That(StoreArtBounds.TryGet(sprite, out ArtBounds b), sprite + " is in the table");
            bool same = Math.Abs(b.X0 * w - x0) < 0.1f && Math.Abs(b.Y0 * h - y0) < 0.1f && Math.Abs(b.X1 * w - x1) < 0.1f && Math.Abs(b.Y1 * h - y1) < 0.1f;
            TestAssert.That(same, sprite + ": ink " + b.X0 * w + " " + b.Y0 * h + " " + b.X1 * w + " " + b.Y1 * h + " should be " + x0 + " " + y0 + " " + x1 + " " + y1);
        }

        private static void Bounds()
        {
            // The boxes LAYOUT.md 1 measured on the extracted pictures.
            Ink("weaponIcon_gatlingGun", 512f, 256f, 5, 84, 504, 165);
            Ink("weaponIcon_AAM4", 512f, 256f, 13, 95, 494, 161);
            Ink("weaponIcon_AAM1", 512f, 256f, 61, 93, 453, 163);
            Ink("weaponIcon_AGM1", 512f, 256f, 59, 89, 444, 165);
            Ink("weaponIcon_bomb_250_glide", 512f, 256f, 69, 91, 440, 150);
            Ink("weaponicon_flares", 232f, 174f, 2, 2, 230, 172);
            Ink("weaponicon_radarJammer", 256f, 256f, 46, 60, 218, 210);
            Ink("weaponIcon_radarContainer1", 1024f, 512f, 234, 76, 787, 403);
            TestAssert.That(!StoreArtBounds.TryGet("a modded weapon's picture", out ArtBounds none) && none.X1 == 0f, "An unknown sprite is not in the table");
            TestAssert.That(!StoreArtBounds.TryGet("", out _) && !StoreArtBounds.TryGet(null, out _), "...nor is no name at all");
            TestAssert.That(!StoreArtBounds.TryGet("weaponicon_flares ", out _) && !StoreArtBounds.TryGet("WEAPONICON_FLARES", out _), "Names match exactly");
            ArtBounds whole = ArtBounds.Whole;
            TestAssert.That(whole.X0 == 0f && whole.Y0 == 0f && whole.X1 == 1f && whole.Y1 == 1f, "The whole sprite is the fallback");
        }

        private static void Fit()
        {
            StoreArtBounds.TryGet("weaponIcon_gatlingGun", out ArtBounds gun);
            ArtPlace p = StoreArt.Fit(gun, 512f, 256f, 10f, 20f, 272f, 56f);
            TestAssert.Near(p.W, 272f, "The gun's ink fills the 272 wide box");
            TestAssert.That(Math.Abs(p.H - 272f * 81f / 499f) < 0.1f, "...with its aspect kept (499 x 81): " + p.H);
            TestAssert.Near(p.X, 10f, "...from the box's left edge");
            TestAssert.Near(p.Y, 20f + (56f - p.H) / 2f, "...centred in the box's height");
            TestAssert.That(p.U0 == gun.X0 && p.U1 == gun.X1 && p.V0 == gun.Y0 && p.V1 == gun.Y1, "...showing only the ink's part of the sprite");

            StoreArtBounds.TryGet("weaponIcon_cargoHook", out ArtBounds hook);
            p = StoreArt.Fit(hook, 512f, 256f, 0f, 0f, 272f, 56f);
            TestAssert.Near(p.H, 56f, "A tall picture (the cargo hook) is limited by the box's height");
            TestAssert.That(Math.Abs(p.W - 56f * 216f / 173f) < 0.1f, "...and keeps its aspect: " + p.W);
            TestAssert.Near(p.X, (272f - p.W) / 2f, "...centred across the box");

            p = StoreArt.Fit(ArtBounds.Whole, 512f, 256f, 0f, 0f, 272f, 56f);
            TestAssert.That(Math.Abs(p.W - 112f) < 0.01f && Math.Abs(p.H - 56f) < 0.01f, "A sprite the table does not know is drawn whole: 2:1 in the box");

            StoreArtBounds.TryGet("weaponicon_radarJammer", out ArtBounds jam);
            p = StoreArt.Fit(jam, 256f, 256f, 0f, 0f, 14f, 14f);
            TestAssert.That(p.W <= 14.001f && p.H <= 14.001f && Math.Abs(p.W - 14f) < 0.01f, "The jammer's art fills its 14 x 14 box across: " + p.W + " x " + p.H);

            TestAssert.That(StoreArt.Fit(gun, 0f, 256f, 0f, 0f, 272f, 56f).W == 0f, "A sprite with no size places nothing");
            TestAssert.That(StoreArt.Fit(gun, 512f, 256f, 0f, 0f, 0f, 56f).W == 0f && StoreArt.Fit(gun, 512f, 256f, 0f, 0f, 272f, -1f).W == 0f, "An empty box places nothing");
            TestAssert.That(StoreArt.Fit(new ArtBounds(0.5f, 0.5f, 0.5f, 0.9f), 512f, 256f, 0f, 0f, 272f, 56f).W == 0f, "A picture with no width places nothing");
        }

        private static void Slice()
        {
            var p = new ArtPlace(10f, 20f, 200f, 40f, 0.1f, 0.2f, 0.9f, 0.6f);
            ArtPlace lit = p.Slice(0f, 0.25f), spent = p.Slice(0.25f, 1f);
            TestAssert.That(lit.X == 10f && Math.Abs(lit.W - 50f) < 0.001f && lit.Y == 20f && lit.H == 40f, "A quarter of the picture is its left quarter");
            TestAssert.That(Math.Abs(lit.U0 - 0.1f) < 0.001f && Math.Abs(lit.U1 - 0.3f) < 0.001f && lit.V0 == 0.2f && lit.V1 == 0.6f, "...of the sprite's part too");
            TestAssert.That(Math.Abs(spent.X - 60f) < 0.001f && Math.Abs(spent.W - 150f) < 0.001f && Math.Abs(spent.U0 - 0.3f) < 0.001f && Math.Abs(spent.U1 - 0.9f) < 0.001f, "The rest is the spent share, from where the lit one ends");
            ArtPlace all = p.Slice(-1f, 2f);
            TestAssert.That(all.X == 10f && all.W == 200f && all.U0 == 0.1f && Math.Abs(all.U1 - 0.9f) < 0.001f, "A slice is held inside the picture");
            TestAssert.That(p.Slice(0.7f, 0.2f).W == 0f, "A backwards slice is empty");
        }
    }
}
